const allTweaks=[]; let n=1;
for(const c of CATEGORIES){for(const row of RAW[c.id]){const [title,desc,risk,mode,undo]=row;allTweaks.push({id:'NV-'+String(n++).padStart(3,'0'),category:c.id,categoryName:c.name,title,desc,risk,mode,undo,reviewed:false,enabled:false});}}
if(allTweaks.length!==120) console.error('Expected 120 entries, got',allTweaks.length);
const state={page:'overview',filter:'all',search:'',risk:'all',sort:'id',tweakId:null,selectedCsv:null,benchmarks:[],history:[],bgAppStatus:{},bgSearch:'',bgFilter:'all',profile:'competitive',matchChecklist:{},notes:localStorage.getItem('novaNotes')||''};
const stored=loadStored();
function loadStored(){try{return JSON.parse(localStorage.getItem('novaV2State')||'{}')}catch{return {}}}
function saveStored(){const safe={version:'3.0.0',tweaks:allTweaks.map(t=>({id:t.id,reviewed:t.reviewed,enabled:t.enabled})),benchmarks:state.benchmarks,history:state.history.slice(0,80),bgAppStatus:state.bgAppStatus,profile:state.profile,matchChecklist:state.matchChecklist,notes:state.notes};localStorage.setItem('novaV2State',JSON.stringify(safe));localStorage.setItem('novaNotes',state.notes||'')}
if(stored.tweaks) for(const saved of stored.tweaks){const t=allTweaks.find(x=>x.id===saved.id);if(t){t.reviewed=!!saved.reviewed;t.enabled=!!saved.enabled}}
state.benchmarks=Array.isArray(stored.benchmarks)?stored.benchmarks:[];state.history=Array.isArray(stored.history)?stored.history:[];state.bgAppStatus=stored.bgAppStatus&&typeof stored.bgAppStatus==='object'?stored.bgAppStatus:{};state.profile=['competitive','balanced','stream'].includes(stored.profile)?stored.profile:'competitive';state.matchChecklist=stored.matchChecklist&&typeof stored.matchChecklist==='object'?stored.matchChecklist:{};
const $content=$('#content'),$toast=$('#toast');let toastTimer;
function toast(msg){$toast.textContent=msg;$toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$toast.classList.remove('show'),2600)}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function riskTag(r){return `<span class="tag ${r==='medium'?'amber':r==='high'?'red':'green'}">${r==='medium'?'MIT BEDACHT':r==='high'?'HOHES RISIKO':'NIEDRIGES RISIKO'}</span>`}
function modeTag(m){return `<span class="tag blue">${safe(m)}</span>`}
function reviewedCount(){return allTweaks.filter(t=>t.reviewed).length}function enabledCount(){return allTweaks.filter(t=>t.enabled).length}
function setPage(page){state.page=page;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb-title').textContent=({overview:'Übersicht',tweaks:'Tweak-Bibliothek',analyzer:'FPS Analyzer',network:'Netzwerk-Lab',restore:'Verlauf & Undo',safety:'Safety Center',settings:'Einstellungen',background:'Background Apps',playbook:'Match Prep'})[page]||'Übersicht';render();$('#sidebar').classList.remove('open');}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function stat(label,value,foot){return `<div class="stat-card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function renderOverview(){const reviewed=reviewedCount(),active=enabledCount();return `${pageHead('PERFORMANCE SUITE / 02','Mehr Kontrolle. <span class="green">Weniger Rätselraten.</span>','120 klar dokumentierte Checks und Tweak-Guides für Fortnite. NOVA führt im Browser keine Windows-Änderungen aus – du entscheidest bewusst, was du prüfst.',`<button class="btn primary" data-action="goto-tweaks">Tweak-Bibliothek öffnen ↗</button><button class="btn ghost" data-action="export-all">Exportieren ↓</button>`)}
<div class="hero-card"><div><div class="eyebrow">NOVA CONTROL CENTER</div><h1>Optimize with<br><span class="green">confidence.</span></h1><p>Keine magischen FPS-Versprechen. Nur nachvollziehbare Schritte, Risiko-Hinweise, lokale Benchmarks und ein Rückweg für dokumentierte Änderungen.</p><div class="hero-actions"><button class="btn primary" data-action="goto-tweaks">120 Tweaks ansehen</button><button class="btn ghost" data-action="goto-playbook">Match Prep öffnen</button><button class="btn ghost" data-action="goto-background">Background Apps prüfen</button><button class="btn ghost" data-action="goto-analyzer">FPS-Log analysieren</button></div></div><div class="readiness"><div class="readiness-head"><span>CHECKLISTEN-FORTSCHRITT</span><span class="green">LOCAL</span></div><div class="readiness-num">${reviewed}<small> / 120</small></div><div class="progress"><span style="width:${reviewed/120*100}%"></span></div><small>${Math.round(reviewed/120*100)}% geprüft · ${active} als geplant markiert</small></div></div>
<div class="grid stats-grid">${stat('TWEAKS INSGESAMT','120','<strong>5</strong> Bereiche · fest definiert')}${stat('GEPRÜFT',reviewed,'<strong>Lokaler</strong> Fortschritt')}${stat('GEPLANT',active,'Nur Checklistenstatus')}${stat('BENCHMARKS',state.benchmarks.length,'<strong>Offline</strong> gespeichert')}</div>
<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Deine Tweak-Bereiche</h2><p>Wähle einen Bereich, um die Checks zu öffnen.</p></div><span class="tag green">5 MODULE</span></div><div class="category-list">${CATEGORIES.map(c=>`<button class="category-row" data-category="${c.id}"><span class="category-icon">${c.icon}</span><span><b>${c.name}</b><small>${c.sub}</small></span><span class="cat-num">${c.count} ↗</span></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Safety first</h2><p>Ein paar Regeln, die NOVA absichtlich nicht umgeht.</p></div><span class="tag amber">SAFE MODE</span></div><div class="activity-list"><div class="activity"><span class="activity-icon">✓</span><div><b>Kein blindes Anwenden</b><small>Browser-Version dokumentiert und erklärt; sie verändert keine Windows-Einstellungen.</small></div></div><div class="activity"><span class="activity-icon">↶</span><div><b>Undo-orientiert</b><small>Checklistenstatus lässt sich zurücksetzen. Für echte PC-Änderungen brauchst du deine eigene Sicherung.</small></div></div><div class="activity"><span class="activity-icon">⌁</span><div><b>Messung statt Marketing</b><small>FPS-Logs und A/B-Benchmarks zeigen, ob ein Unterschied messbar ist.</small></div></div></div><div class="notice"><span class="notice-icon">!</span><div><b>Browser-Modus aktiv</b><p>Für echte Systemfunktionen braucht es später einen separat geprüften Windows-Client mit klaren Berechtigungen.</p></div></div><button class="btn ghost" style="margin-top:13px;width:100%" data-action="goto-safety">Safety Center öffnen</button></section></div>`}
function renderTweakCard(t){return `<article class="tweak-card"><div class="tweak-top"><span class="tweak-id">${t.id}</span><div class="row-end">${t.reviewed?'<span class="tag green">GEPRÜFT</span>':''}${riskTag(t.risk)}</div></div><h3>${safe(t.title)}</h3><p>${safe(t.desc)}</p><div class="tweak-bottom"><span class="tweak-mode">${safe(t.mode)}${t.enabled?' · GEPLANT':''}</span><button class="btn ghost small" data-open-tweak="${t.id}">Details ↗</button></div></article>`}
function renderTweaks(){let list=allTweaks.filter(t=>(state.filter==='all'||t.category===state.filter)&&(state.risk==='all'||t.risk===state.risk)&&(`${t.title} ${t.desc} ${t.id} ${t.categoryName}`.toLowerCase().includes(state.search.toLowerCase())));if(state.sort==='risk')list.sort((a,b)=>({low:0,medium:1,high:2}[a.risk]-{low:0,medium:1,high:2}[b.risk]));else if(state.sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));else list.sort((a,b)=>Number(a.id.slice(3))-Number(b.id.slice(3)));return `${pageHead('TWEAK LIBRARY / 120 ITEMS','The <span class="green">Tweak Library.</span>','120 Einträge in fünf Bereichen. Öffne einen Eintrag für Erklärung, Risiko, Modus und Rückweg. „Geplant“ ist nur ein lokaler Marker, kein ausgeführter Systemtweak.',`<button class="btn ghost" data-action="export-all">Daten exportieren ↓</button>`)}<div class="filters"><div class="search"><input id="tweak-search" placeholder="Tweak, ID oder Bereich suchen …" value="${safe(state.search)}" aria-label="Tweaks suchen"></div><select class="select" id="risk-filter" aria-label="Risiko filtern"><option value="all" ${state.risk==='all'?'selected':''}>Alle Risiken</option><option value="low" ${state.risk==='low'?'selected':''}>Niedrig</option><option value="medium" ${state.risk==='medium'?'selected':''}>Mit Bedacht</option></select><select class="select" id="sort-filter" aria-label="Sortierung"><option value="id" ${state.sort==='id'?'selected':''}>Standard</option><option value="title" ${state.sort==='title'?'selected':''}>Name A–Z</option><option value="risk" ${state.sort==='risk'?'selected':''}>Risiko zuerst</option></select></div><div class="library-layout"><aside class="panel filter-panel"><div class="filter-title">KATEGORIEN</div><button class="filter-option ${state.filter==='all'?'active':''}" data-filter="all">Alle Tweaks <span>120</span></button>${CATEGORIES.map(c=>`<button class="filter-option ${state.filter===c.id?'active':''}" data-filter="${c.id}">${c.name}<span>${c.count}</span></button>`).join('')}<div class="divider"></div><div class="filter-title">FORTSCHRITT</div><div style="font-size:11px;color:#8c9a8f;margin:10px 0">${reviewedCount()} / 120 geprüft</div><div class="progress"><span style="width:${reviewedCount()/120*100}%"></span></div><button class="btn ghost small" style="width:100%;margin-top:8px" data-action="reset-checks">Status zurücksetzen</button></aside><div><div class="count-line">${list.length} ERGEBNISSE · ${reviewedCount()} GEPRÜFT · ${enabledCount()} GEPLANT</div><div class="tweak-grid">${list.map(renderTweakCard).join('')||'<div class="empty-state">Keine Tweaks gefunden. Passe Suche oder Filter an.</div>'}</div></div></div>`}
function renderAnalyzer(){return `${pageHead('PERFORMANCE LAB / CSV','FPS <span class="green">Analyzer.</span>','Importiere ein CSV-Log, um Durchschnitt, Median, geschätzte 1%-Low-Werte und Framezeit-Spitzen zu analysieren. Dateien werden im Browser verarbeitet.',`<button class="btn ghost" data-action="sample-csv">Beispiel-CSV ↓</button>`)}<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Log importieren</h2><p>Unterstützte Spalten: timestamp, fps, optional frametime_ms</p></div><span class="tag green">LOCAL ONLY</span></div><div class="analyzer-drop"><div style="font-size:25px;color:var(--green)">⇧</div><strong>CSV-Datei auswählen</strong><p>Max. 5 MB · keine Datei wird hochgeladen</p><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="CSV-Datei auswählen" class="select"></div><div class="notice"><span class="notice-icon">i</span><div><b>Interpretation</b><p>1%-Low ist hier eine Perzentil-Schätzung aus den vorhandenen Samples. Die Messqualität hängt vom Logger und der Abtastrate ab.</p></div></div></section><section class="panel"><div class="panel-head"><div><h2>Messbedingungen</h2><p>Für einen fairen A/B-Vergleich</p></div></div><div class="form-row"><div class="field"><label for="bench-name">Name des Tests</label><input id="bench-name" placeholder="z. B. Baseline — DX12"></div><div class="field"><label for="bench-version">Spielversion / Modus</label><input id="bench-version" placeholder="Version, Map, Modus"></div></div><div class="field" style="margin-top:12px"><label for="bench-notes">Notizen</label><textarea id="bench-notes" placeholder="Auflösung, FPS-Limit, Treiber, Testdauer …"></textarea></div><button class="btn primary" style="margin-top:13px" data-action="save-benchmark" id="save-benchmark" disabled>Analyse als Benchmark speichern</button></section></div><div id="analysis-output" style="margin-top:15px"><section class="panel"><div class="empty-state">Noch kein Log geladen. Importiere eine CSV oder lade die Beispiel-Datei.</div></section></div>${renderSavedBenchmarks()}`}
function renderSavedBenchmarks(){const items=state.benchmarks;let comparison='';if(items.length>=2){const a=items[0],b=items[1];const d=(x,y)=>x-y;const pct=(x,y)=>y?((x-y)/y*100):0;const cell=(label,x,y,unit,lowerBetter=false)=>{const delta=d(x,y),p=pct(x,y);const good=delta===0?'delta-neutral':((lowerBetter?delta<0:delta>0)?'delta-good':'delta-bad');return `<div class="metric"><small>${label}</small><b>${x.toFixed(1)}${unit}</b><span class="${good}">${delta>0?'+':''}${delta.toFixed(1)}${unit} (${p>0?'+':''}${p.toFixed(1)}%) vs previous</span></div>`};comparison=`<div class="analyzer-results">${cell('AVG FPS',a.avg,b.avg,' FPS')}${cell('EST. 1%-LOW',a.low,b.low,' FPS')}${cell('P99 FRAME TIME',a.p99,b.p99,' ms',true)}${cell('MEDIAN FPS',a.median,b.median,' FPS')}</div><p class="chart-note">Neuester Benchmark: ${safe(a.name)} · Vergleichsbasis: ${safe(b.name)}. Unterschied ist nur belastbar, wenn Szene, Dauer und Einstellungen vergleichbar waren.</p>`}return `<section class="panel benchmark-panel" id="saved-benchmarks"><div class="panel-head"><div><h2>Saved Benchmarks <span class="green">/ A-B</span></h2><p>${items.length} lokal gespeicherte Messungen · neueste zuerst</p></div><span class="tag green">LOCAL ONLY</span></div>${items.length>=2?comparison:''}${items.length?`<div style="overflow-x:auto"><table class="benchmark-table"><thead><tr><th>TEST</th><th>AVG FPS</th><th>1%-LOW*</th><th>P99 FRAME</th><th>SAMPLES</th><th>DATUM</th></tr></thead><tbody>${items.slice(0,10).map(x=>`<tr><td><b>${safe(x.name)}</b><br><span class="muted">${safe(x.version||'Ohne Versionsnotiz')}</span></td><td>${Number(x.avg).toFixed(1)}</td><td>${Number(x.low).toFixed(1)}</td><td>${Number(x.p99).toFixed(2)} ms</td><td>${x.samples}</td><td>${new Date(x.date).toLocaleDateString('de-DE')}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">*1%-Low ist eine Schätzung aus den importierten Samples, kein Ersatz für einen standardisierten Benchmark.</p>`:'<div class="benchmark-empty">Noch keine Benchmarks gespeichert. Importiere oben eine CSV und klicke auf „Analyse als Benchmark speichern“.'}</section>`}
function renderNetwork(){return `${pageHead('NETWORK LAB / DIAGNOSTICS','Know your <span class="green">connection.</span>','Dieses Modul führt optionale HTTP-Erreichbarkeitsmessungen aus. Die Dauer einer Web-Anfrage ist kein Fortnite-Server-Ping und misst weder ICMP noch In-Game-Routing.',`<button class="btn ghost" data-action="network-info">Messhinweise</button>`)}<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>HTTP-Verbindungstest</h2><p>Misst die Antwortzeit einer HTTPS-Anfrage.</p></div><span class="tag amber">KEIN IN-GAME-PING</span></div><div class="network-box"><div class="eyebrow">WEB REQUEST DURATION</div><div class="network-stat" id="net-result">— <small>ms</small></div><p id="net-status" style="font-size:11px">Bereit für einen Test. Die Messung braucht Internetzugang.</p><button class="btn primary" style="margin-top:15px" data-action="run-network" id="run-network">HTTP-Test starten ↗</button></div></section><section class="panel"><h2>So liest du die Ergebnisse</h2><p style="font-size:12px;margin:10px 0 15px">Ein HTTP-Test enthält DNS-, Verbindungs- und TLS-Anteile und hängt vom Zielserver ab. Er kann nicht direkt mit dem Ping aus Fortnite gleichgesetzt werden.</p><div class="activity-list"><div class="activity"><span class="activity-icon">1</span><div><b>In-Game-Statistik nutzen</b><small>Für den tatsächlichen Server-Ping und Paketverlust nutze die Netzwerkstatistik im Spiel, falls verfügbar.</small></div></div><div class="activity"><span class="activity-icon">2</span><div><b>Mehrfach messen</b><small>Vergleiche mehrere Tests zu unterschiedlichen Zeiten; einzelne Werte können täuschen.</small></div></div><div class="activity"><span class="activity-icon">3</span><div><b>Keine Wunder-Tweaks</b><small>DNS-Wechsel oder Registry-Presets garantieren keinen niedrigeren Ping.</small></div></div></div></section></div>`}
