const PLAYBOOKS = {
 competitive:{name:'Competitive / Low Latency',desc:'Priorisiert stabile Frametime und niedrige Zusatzlast. Keine Grafik- oder Registry-Magie; messe Änderungen einzeln.',focus:['Aufnahme/Replay testweise aus','Downloads pausieren','Stabiles FPS-Limit vergleichen','Optionale Overlays einzeln prüfen']},
 balanced:{name:'Balanced / Alltag',desc:'Behält Komfortfunktionen bei und konzentriert sich auf klare, reversible Checks statt aggressiver Abschaltungen.',focus:['Nur echte Lastquellen schließen','Chat und benötigte Peripherie behalten','FPS-Limit passend zum System','Temperatur und Frametimes beobachten']},
 stream:{name:'Streaming / Recording',desc:'Behandelt Stream- und Capture-Apps als benötigte Last. Ziel ist stabile Ausgabe, nicht möglichst wenige Prozesse.',focus:['Encoder-Auslastung beobachten','Aufnahme auf separater Testszene prüfen','Upload-Auslastung im Blick behalten','Unnötige Downloads pausieren']}
};
function renderPlaybook(){const profile=PLAYBOOKS[state.profile]||PLAYBOOKS.competitive;const done=MATCH_STEPS.filter(x=>state.matchChecklist[x.id]).length;return `${pageHead('NOVA FREE / PRE-GAME WORKFLOW','Match Prep <span class="green">Playbook.</span>','Eine klare, kostenlose Pre-Game-Routine für FPS-Stabilität und Latenz-Diagnose. Das Profil erstellt einen Plan, ändert aber keine Windows-Einstellungen.',`<button class="btn ghost" data-action="reset-match">Checkliste zurücksetzen</button><button class="btn primary" data-action="goto-background">Background Apps ↗</button>`)}
<section class="hero-card playbook-hero"><div><div class="eyebrow">FREE PERFORMANCE WORKFLOW</div><h1>Less background noise.<br><span class="green">More measurable results.</span></h1><p>Arbeite die Liste ab, teste nur eine Änderung gleichzeitig und behalte die Einstellung nur, wenn der Vergleich tatsächlich besser ausfällt.</p><div class="hero-actions"><button class="btn primary" data-action="goto-analyzer">FPS-Log analysieren ↗</button><button class="btn ghost" data-action="goto-tweaks">120 Checks durchsuchen</button></div></div><div class="readiness"><div class="readiness-head"><span>SESSION READINESS</span><span class="green">LOCAL</span></div><div class="readiness-num">${done}<small> / ${MATCH_STEPS.length}</small></div><div class="progress"><span style="width:${done/MATCH_STEPS.length*100}%"></span></div><small>${Math.round(done/MATCH_STEPS.length*100)}% der Pre-Game-Schritte erledigt</small></div></section>
<section class="panel profile-panel"><div class="panel-head"><div><h2>Wähle dein Session-Profil</h2><p>Das Profil passt die Empfehlungen an — es schaltet keine Funktionen automatisch um.</p></div><span class="tag green">FREE · OHNE PAYWALL</span></div><div class="profile-grid">${Object.entries(PLAYBOOKS).map(([id,p])=>`<button class="profile-card ${state.profile===id?'selected':''}" data-profile="${id}" aria-pressed="${state.profile===id}"><span class="profile-icon">${id==='competitive'?'⚡':id==='balanced'?'◈':'▣'}</span><b>${safe(p.name)}</b><small>${safe(p.desc)}</small><span class="profile-select">${state.profile===id?'AKTIV':'PROFIL WÄHLEN'}</span></button>`).join('')}</div><div class="notice" style="margin-top:14px"><span class="notice-icon">i</span><div><b>${safe(profile.name)}</b><p>${safe(profile.desc)}</p><p class="profile-focus"><strong>Fokus:</strong> ${profile.focus.map(safe).join(' · ')}</p></div></div></section>
<section class="panel match-check-panel"><div class="panel-head"><div><h2>Pre-Game Checklist</h2><p>Markiere einen Punkt erst, nachdem du ihn selbst geprüft hast.</p></div><span class="tag">${done}/${MATCH_STEPS.length} ABGEHAKT</span></div><div class="match-step-list">${MATCH_STEPS.map((step,i)=>`<label class="match-step ${state.matchChecklist[step.id]?'checked':''}"><input type="checkbox" data-match-check="${step.id}" ${state.matchChecklist[step.id]?'checked':''}><span class="match-step-num">${String(i+1).padStart(2,'0')}</span><span class="match-step-body"><b>${safe(step.title)}</b><small>${safe(step.desc)}</small><em>${safe(step.group)} · ${safe(step.impact)}</em></span><span class="priority ${step.priority==='MUSS'?'must':step.priority==='HOCH'?'high':''}">${safe(step.priority)}</span></label>`).join('')}</div></section>
<section class="panel protected-panel"><div class="panel-head"><div><h2>Diese Dinge bleiben an</h2><p>Mehr Prozesse zu beenden bedeutet nicht automatisch mehr FPS.</p></div><span class="tag red">PROTECTED</span></div><div class="protected-grid"><div><b>Windows-Sicherheit / Antivirus</b><p>Nicht deaktivieren oder beenden.</p></div><div><b>GPU-, Audio- und Eingabetreiber</b><p>Nicht über Task-Manager beenden.</p></div><div><b>Unbekannte Prozesse & Dienste</b><p>Erst identifizieren; im Zweifel unangetastet lassen.</p></div><div><b>Epic / Fortnite Kernprozesse</b><p>Nicht schließen, solange das Spiel oder der Launcher sie benötigt.</p></div></div></section>`}

