function bgStatus(id){return state.bgAppStatus[id]||'unknown'}
function renderBackground(){const done=BG_APPS.filter(a=>bgStatus(a.id)==='done').length;const found=BG_APPS.filter(a=>bgStatus(a.id)==='found').length;const visibleApps=BG_APPS.filter(a=>(state.bgFilter==='all'||(state.bgFilter==='protected'?a.risk==='high':state.bgFilter==='optional'?a.risk!=='high':bgStatus(a.id)===state.bgFilter))&&(`${a.name} ${a.desc} ${a.impact} ${a.group}`.toLowerCase().includes(state.bgSearch.toLowerCase())));return `${pageHead('PERFORMANCE WORKSPACE / BACKGROUND LOAD','Background Apps <span class="green">Control.</span>','Finde optionale Lastquellen vor dem Match. Diese Browser-Version kann deinen Windows-Prozessbaum nicht sehen und beendet keine Apps automatisch: du bestätigst hier nur, was du im Task-Manager selbst geprüft hast.',`<button class="btn ghost" data-action="reset-bg">Status zurücksetzen</button><button class="btn primary" data-action="goto-tweaks">FPS-Tweaks öffnen ↗</button>`)}
<div class="grid stats-grid">${stat('CHECKLISTE',`${done} / ${BG_APPS.length}`,'<strong>Manuell</strong> bestätigt')}${stat('IM TASK-MANAGER GEFUNDEN',found,'<strong>Nur</strong> Statusnotiz')}${stat('OPTIONALE KANDIDATEN',BG_APPS.filter(a=>a.risk!=='high').length,'<strong>Einzeln</strong> prüfen')}${stat('GESCHÜTZTE GRUPPEN',3,'<strong>Nicht</strong> beenden')}</div>
<div class="notice"><span class="notice-icon">!</span><div><b>Wichtig: Kein automatisches Prozess-Killen</b><p>Nutze Windows Task-Manager (Strg + Umschalt + Esc). Beende nur Apps, die du erkennst und gerade nicht brauchst. Keine unbekannten Prozesse, Windows-Dienste, Antivirus- oder Treiberprozesse schließen. Pausiere Downloads statt wichtige Launcher zu beenden.</p></div></div>
<section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>Pre-Game Background Checklist</h2><p>Suche nach Apps und filtere optionale Kandidaten von geschützten Gruppen.</p></div><span class="tag green">LOCAL CHECKLIST</span></div><div class="bg-filter-row"><input id="bg-search" class="bg-search" placeholder="App, Ressourcen oder Hinweis suchen …" value="${safe(state.bgSearch)}" aria-label="Background Apps suchen"><select id="bg-filter" class="select" aria-label="Background Apps filtern"><option value="all" ${state.bgFilter==='all'?'selected':''}>Alle Gruppen</option><option value="optional" ${state.bgFilter==='optional'?'selected':''}>Optionale Kandidaten</option><option value="protected" ${state.bgFilter==='protected'?'selected':''}>Geschützte Gruppen</option><option value="unknown" ${state.bgFilter==='unknown'?'selected':''}>Status: offen</option><option value="found" ${state.bgFilter==='found'?'selected':''}>Status: gefunden</option><option value="done" ${state.bgFilter==='done'?'selected':''}>Status: geprüft</option></select></div><div class="count-line">${visibleApps.length} VON ${BG_APPS.length} EINTRÄGEN</div><div class="bg-app-list">${visibleApps.map(a=>{const st=bgStatus(a.id);const protectedApp=a.risk==='high';return `<article class="bg-app-row ${protectedApp?'protected':''}"><div class="bg-app-main"><div class="bg-app-icon">${protectedApp?'⊘':'◌'}</div><div class="bg-app-copy"><div class="bg-app-heading"><h3>${safe(a.name)}</h3><span class="tag ${protectedApp?'red':a.risk==='medium'?'amber':'green'}">${safe(a.group)}</span></div><p>${safe(a.desc)}</p><div class="bg-app-meta"><span>IMPACT: ${safe(a.impact)}</span><span>${protectedApp?'SICHERHEITSRELEVANT':'OPTIONAL / TESTEN'}</span></div><small class="bg-app-action"><b>Empfohlener Schritt:</b> ${safe(a.action)}</small></div></div><div class="bg-app-controls"><span class="bg-status ${st==='done'?'is-done':st==='found'?'is-found':''}">${st==='done'?'ERLEDIGT':st==='found'?'GEFUNDEN':'OFFEN'}</span><button class="btn ${st==='done'?'ghost':'primary'} small" data-bg-cycle="${a.id}">${st==='unknown'?'Als gefunden markieren':st==='found'?(protectedApp?'Als geprüft markieren':'Als geprüft/erledigt markieren'):'Zurücksetzen'}</button></div></article>`}).join('')}</div></section>
<section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>Windows Task-Manager — sicherer Ablauf</h2><p>Manuelle Schritte für Windows 10/11.</p></div><span class="tag amber">NO AUTO ACTIONS</span></div><div class="bg-steps"><div><b>01</b><h3>Prozesse sortieren</h3><p>Task-Manager → Prozesse. Sortiere CPU, Arbeitsspeicher und Netzwerk, um auffällige Last zu erkennen.</p></div><div><b>02</b><h3>App erkennen</h3><p>Prüfe Name und Herausgeber. Wenn du nicht sicher bist, was ein Prozess tut, beende ihn nicht.</p></div><div><b>03</b><h3>Normal schließen</h3><p>Schließe zuerst über das jeweilige App-Menü. „Task beenden“ nur bei bekannten, optionalen Apps, die nicht reagieren.</p></div><div><b>04</b><h3>Im Spiel messen</h3><p>Vergleiche dieselbe Szene, dieselbe Dauer und die 1%-Lows/Frametimes. Wenn es nichts verbessert, lass die App offen.</p></div></div></section>`}
function renderRestore(){return `${pageHead('LOCAL HISTORY / REVERSIBILITY','Verlauf & <span class="green">Undo.</span>','NOVA protokolliert lokale Statusänderungen, Benchmark-Speicherungen und Rücksetzungen. Es kann keine externen Windows-Änderungen automatisch zurückrollen.',`<button class="btn ghost" data-action="export-all">Verlauf exportieren ↓</button><button class="btn danger" data-action="clear-history">Verlauf leeren</button>`)}<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Letzte Aktionen</h2><p>Lokales Protokoll dieses Browsers.</p></div><span class="tag">${state.history.length} EINTRÄGE</span></div><div class="history-list">${state.history.length?state.history.map(h=>`<div class="history-item"><span class="history-dot"></span><div><b>${safe(h.title)}</b><small>${safe(h.detail||'')} · ${new Date(h.time).toLocaleString('de-DE')}</small></div><span class="tag">${safe(h.type||'LOG')}</span></div>`).join(''):'<div class="empty-state">Noch keine Aktionen. Geprüfte Tweaks und gespeicherte Benchmarks erscheinen hier.</div>'}</div></section><section class="panel"><h2>Was Undo bedeutet</h2><p style="font-size:12px;margin:10px 0 15px">In dieser Browser-Version bedeutet Undo, dass du einen lokalen NOVA-Status zurücksetzt. Da die App keine Windows-Einstellungen verändert, kann sie auch keine echten Systemwerte zurückstellen.</p><div class="safety-list"><div class="safety-item"><span class="safety-symbol">↶</span><div><b>Checklistenstatus zurücksetzen</b><p>Entfernt die Markierung „geprüft/geplant“ aus der Bibliothek.</p><button class="btn ghost small" style="margin-top:10px" data-action="reset-checks">Status zurücksetzen</button></div></div><div class="safety-item"><span class="safety-symbol">⇩</span><div><b>Backup exportieren</b><p>Speichere lokale Einstellungen, Notizen und Benchmarks als JSON-Datei.</p><button class="btn ghost small" style="margin-top:10px" data-action="export-all">Backup exportieren</button></div></div></div></section></div>`}
function renderSafety(){return `${pageHead('SAFETY CENTER / GUARDRAILS','Performance without <span class="green">reckless tweaks.</span>','Die Risikoanzeige hilft beim Einordnen, ersetzt aber keine Windows-Dokumentation oder Hardware-spezifische Beratung. NOVA läuft derzeit ohne Administratorrechte und ohne Systemzugriff.',`<button class="btn ghost" data-action="goto-tweaks">Bibliothek öffnen</button>`)}<div class="safety-list"><div class="safety-item"><span class="safety-symbol">✓</span><div><b>120 Checks + Match Prep, keine versteckten Systemaktionen</b><p>Die Browser-App bietet Erklärungen, Checklisten, Messungen und Exporte. „Geplant“ ist kein echter Windows-Schalter.</p></div></div><div class="safety-item"><span class="safety-symbol">!</span><div><b>Keine Defender-/Firewall-/Secure-Boot-Abschaltung</b><p>Sicherheitsfunktionen werden nicht als FPS-Tweak empfohlen. Auch wichtige Windows-Dienste werden nicht pauschal deaktiviert.</p></div></div><div class="safety-item"><span class="safety-symbol">↶</span><div><b>Vor jeder echten PC-Änderung: Rückweg sichern</b><p>Notiere den Ausgangswert, ändere nur eine Sache auf einmal und teste reproduzierbar. Bei systemweiten Änderungen nutze die Windows-eigenen Wiederherstellungsfunktionen.</p></div></div><div class="safety-item"><span class="safety-symbol">⌁</span><div><b>Benchmarks können schwanken</b><p>FPS hängen von Szene, Treiber, Temperatur, Spielupdate, Auflösung und Hintergrundlast ab. Ein höherer Durchschnitt garantiert keine besseren 1%-Lows.</p></div></div><div class="safety-item"><span class="safety-symbol">🔒</span><div><b>Lokale Daten und Datenschutz</b><p>Checklisten und Notizen bleiben im Local Storage dieses Browsers, bis du sie löschst. Exporte können private Pfade oder Notizen enthalten; prüfe sie vor dem Teilen.</p></div></div></div>`}
function renderSettings(){return `${pageHead('PREFERENCES / LOCAL DATA','NOVA <span class="green">Settings.</span>','Passe lokale Einstellungen an, exportiere deine Daten oder setze die Browser-App zurück.',`<button class="btn ghost" data-action="export-all">Alle Daten exportieren ↓</button>`)}<div class="grid two-col"><section class="panel"><h2>Lokale Daten</h2><p style="font-size:12px;margin:8px 0 17px">Fortschritt: ${reviewedCount()} geprüft · ${enabledCount()} geplant · ${state.benchmarks.length} Benchmarks.</p><div class="field"><label for="notes">Persönliche Notizen / Testplan</label><textarea id="notes" placeholder="PC-Modell, GPU, Auflösung, Ziel-FPS, Testbedingungen …">${safe(state.notes)}</textarea></div><div class="modal-actions"><button class="btn primary" data-action="save-notes">Notizen speichern</button><button class="btn ghost" data-action="export-all">Backup exportieren</button></div><div class="divider"></div><button class="btn danger" data-action="reset-all">Lokale NOVA-Daten zurücksetzen</button></section><section class="panel"><h2>Über diese Version</h2><p style="font-size:12px;margin:8px 0 16px">NOVA FN Optimizer Free Browser Dashboard · Build 3.0.0</p><div class="pill-list"><span class="pill">120 TWEAKS</span><span class="pill">CSV ANALYZER</span><span class="pill">LOCAL STORAGE</span><span class="pill">PWA-READY</span></div><div class="divider"></div><h3>Plattform-Status</h3><p style="font-size:11px">Browser-Dashboard und Grundlage für einen späteren Windows-Client. Ein echter Windows-Client muss separat entwickelt, signiert und auf einem Windows-PC getestet werden; diese ZIP-Datei ist keine EXE.</p><div class="notice"><span class="notice-icon">i</span><div><b>Installationshinweis</b><p>Für PWA-Installation muss die App über HTTPS oder localhost bereitgestellt werden. Eine lokal geöffnete HTML-Datei reicht nicht für alle Installations- und Offline-Funktionen.</p></div></div></section></div>`}
function render(){const map={overview:renderOverview,tweaks:renderTweaks,analyzer:renderAnalyzer,network:renderNetwork,background:renderBackground,playbook:renderPlaybook,restore:renderRestore,safety:renderSafety,settings:renderSettings};$content.innerHTML=(map[state.page]||renderOverview)();bindPage();}
function addHistory(title,detail,type='STATUS'){state.history.unshift({title,detail,type,time:Date.now()});state.history=state.history.slice(0,80);saveStored()}
function openTweak(id){const t=allTweaks.find(x=>x.id===id);if(!t)return;state.tweakId=id;const c=CATEGORIES.find(x=>x.id===t.category);$('#modal-body').innerHTML=`<div class="detail-id">${t.id} / ${safe(c.name.toUpperCase())}</div><div class="detail-header"><h2 id="modal-title">${safe(t.title)}</h2>${riskTag(t.risk)}</div><p class="detail-description">${safe(t.desc)}</p><div class="detail-meta"><div class="meta-cell"><small>Risiko</small><b>${t.risk==='low'?'Niedrig':t.risk==='medium'?'Mit Bedacht':'Hoch'}</b></div><div class="meta-cell"><small>Aktionstyp</small><b>${safe(t.mode)}</b></div><div class="meta-cell"><small>Status</small><b>${t.reviewed?'Geprüft':'Nicht geprüft'}</b></div></div><div class="detail-section"><h3>Worum geht es?</h3><p>${safe(t.desc)} Dieser Eintrag ist eine Anleitung bzw. Diagnose-Checkliste. Die Browser-Version verändert keine Windows-Einstellung und behauptet nicht, dass dieser Schritt FPS erhöht.</p></div><div class="detail-section"><h3>Rückweg / Schutz</h3><p>${safe(t.undo)}</p></div><div class="detail-section"><h3>Empfohlener Ablauf</h3><p>1. Ausgangszustand notieren. 2. Nur diesen einen Punkt prüfen. 3. Eine reproduzierbare Fortnite-Szene testen. 4. Ergebnis dokumentieren und bei schlechterem Ergebnis zurückgehen.</p></div><div class="notice"><span class="notice-icon">!</span><div><b>Nur lokaler Status</b><p>„Als geplant markieren“ ist kein echter Apply-Schalter und ändert keine Windows-Einstellungen.</p></div></div><div class="modal-actions"><button class="btn primary" data-modal-action="review" data-id="${t.id}">${t.reviewed?'Als ungeprüft markieren':'Als geprüft markieren'}</button><button class="btn ghost" data-modal-action="toggle" data-id="${t.id}">${t.enabled?'Plan-Markierung entfernen':'Als geplant markieren'}</button><button class="btn ghost" data-modal-action="close">Schließen</button></div>`;$('#modal-backdrop').hidden=false;$('#modal-close').focus();}
function closeModal(){$('#modal-backdrop').hidden=true;state.tweakId=null}
function bindPage(){
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;render()}));
$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.category;setPage('tweaks')}));
$$('[data-open-tweak]').forEach(b=>b.addEventListener('click',()=>openTweak(b.dataset.openTweak)));
const search=$('#tweak-search');if(search)search.addEventListener('input',e=>{const pos=e.target.selectionStart;state.search=e.target.value;const y=window.scrollY;render();const n=$('#tweak-search');n.focus();n.setSelectionRange(pos,pos);window.scrollTo(0,y)});
const risk=$('#risk-filter');if(risk)risk.addEventListener('change',e=>{state.risk=e.target.value;render()});const sort=$('#sort-filter');if(sort)sort.addEventListener('change',e=>{state.sort=e.target.value;render()});
$$('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset.action,b)));
$$('[data-profile]').forEach(b=>b.addEventListener('click',()=>{state.profile=b.dataset.profile;saveStored();addHistory('Match-Prep-Profil geändert',PLAYBOOKS[state.profile].name,'PROFILE');render();toast('Profil ausgewählt. Es wurden keine Systemwerte geändert.')}));
$$('[data-match-check]').forEach(c=>c.addEventListener('change',()=>{state.matchChecklist[c.dataset.matchCheck]=c.checked;saveStored();addHistory(c.checked?'Match-Prep-Schritt erledigt':'Match-Prep-Schritt zurückgesetzt',MATCH_STEPS.find(x=>x.id===c.dataset.matchCheck)?.title||c.dataset.matchCheck,c.checked?'CHECK':'UNDO');render();}));
const bgSearch=$('#bg-search');if(bgSearch)bgSearch.addEventListener('input',e=>{state.bgSearch=e.target.value;render();const n=$('#bg-search');n?.focus();if(n)n.setSelectionRange(state.bgSearch.length,state.bgSearch.length)});const bgFilter=$('#bg-filter');if(bgFilter)bgFilter.addEventListener('change',e=>{state.bgFilter=e.target.value;render()});
$$('[data-bg-cycle]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.bgCycle;const a=BG_APPS.find(x=>x.id===id);if(!a)return;const cur=bgStatus(id);const next=cur==='unknown'?'found':cur==='found'?'done':'unknown';state.bgAppStatus[id]=next;saveStored();addHistory('Background-App-Status geändert',`${a.name}: ${next==='done'?'geprüft/erledigt':next==='found'?'im Task-Manager gefunden':'offen'}`,'BG-APP');render();toast('Nur Statusnotiz gespeichert – keine App wurde beendet.')}));
const file=$('#csv-file');if(file)file.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)readCsv(f)});
const notes=$('#notes');if(notes)notes.addEventListener('input',e=>state.notes=e.target.value);
}
function handleAction(action,el){switch(action){case'goto-tweaks':setPage('tweaks');break;case'goto-analyzer':setPage('analyzer');break;case'goto-background':setPage('background');break;case'goto-playbook':setPage('playbook');break;case'reset-match':if(confirm('Match-Prep-Checkliste wirklich zurücksetzen?')){state.matchChecklist={};saveStored();addHistory('Match-Prep zurückgesetzt','Alle Match-Prep-Checkboxen geleert','UNDO');render();toast('Match-Prep zurückgesetzt.')}break;case'reset-bg':if(confirm('Alle Background-App-Statusnotizen zurücksetzen?')){state.bgAppStatus={};saveStored();addHistory('Background-App-Status zurückgesetzt','Manuelle Checkliste geleert','UNDO');render();toast('Background-App-Status zurückgesetzt.')}break;case'goto-safety':setPage('safety');break;case'export-all':exportAll();break;case'reset-checks':if(confirm('Alle 120 Checklistenstatus-Markierungen zurücksetzen?')){allTweaks.forEach(t=>{t.reviewed=false;t.enabled=false});addHistory('Checklistenstatus zurückgesetzt','120 Einträge auf ungeprüft/nicht geplant gesetzt','UNDO');saveStored();render();toast('Checklistenstatus zurückgesetzt.')}break;case'clear-history':if(confirm('Lokalen Verlauf leeren?')){state.history=[];saveStored();render();toast('Verlauf geleert.')}break;case'reset-all':if(confirm('Alle lokalen NOVA-Daten, Notizen und Benchmarks löschen?')){allTweaks.forEach(t=>{t.reviewed=false;t.enabled=false});state.history=[];state.benchmarks=[];state.bgAppStatus={};state.matchChecklist={};state.profile='competitive';state.notes='';localStorage.removeItem('novaV2State');localStorage.removeItem('novaNotes');render();toast('Lokale NOVA-Daten zurückgesetzt.')}break;case'save-notes':state.notes=$('#notes')?.value||'';saveStored();addHistory('Notizen gespeichert','Lokale Testnotizen aktualisiert','SAVE');toast('Notizen gespeichert.');break;case'sample-csv':download('nova-sample-fps.csv','timestamp,fps,frametime_ms\n0,144,6.94\n1,142,7.04\n2,138,7.25\n3,119,8.40\n4,145,6.90\n5,143,6.99\n6,92,10.87\n7,140,7.14\n8,144,6.94\n9,141,7.09\n10,136,7.35\n11,145,6.90\n','text/csv');toast('Beispiel-CSV erstellt.');break;case'save-benchmark':saveBenchmark();break;case'run-network':runNetwork(el);break;case'network-info':showModal('HTTP-Test richtig einordnen','Die Messung ist nur die Dauer einer HTTPS-Anfrage an einen Web-Endpunkt. Sie ist kein ICMP-Ping und kein Fortnite-Server-Ping. Der Browser kann außerdem Netzwerkbedingungen nicht vollständig kontrollieren.');break;}}
function showModal(title,body){$('#modal-body').innerHTML=`<div class="eyebrow">NOVA INFORMATION</div><h2 id="modal-title">${safe(title)}</h2><p class="modal-intro">${safe(body)}</p><div class="modal-actions"><button class="btn primary" data-modal-action="close">Verstanden</button></div>`;$('#modal-backdrop').hidden=false;}
$('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$('#modal-body').addEventListener('click',e=>{const b=e.target.closest('[data-modal-action]');if(!b)return;const t=allTweaks.find(x=>x.id===b.dataset.id);if(b.dataset.modalAction==='close'){closeModal();return}if(!t)return;if(b.dataset.modalAction==='review'){t.reviewed=!t.reviewed;addHistory(t.reviewed?'Tweak als geprüft markiert':'Tweak auf ungeprüft gesetzt',`${t.id} · ${t.title}`,t.reviewed?'REVIEW':'UNDO')}if(b.dataset.modalAction==='toggle'){t.enabled=!t.enabled;addHistory(t.enabled?'Tweak als geplant markiert':'Plan-Markierung entfernt',`${t.id} · ${t.title}`,t.enabled?'PLAN':'UNDO')}saveStored();closeModal();render();toast('Lokaler Status aktualisiert. Keine Windows-Änderung ausgeführt.');});
function download(filename,text,type='application/json'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportAll(){const data={app:'NOVA FN Optimizer',version:'3.0.0',exportedAt:new Date().toISOString(),notice:'Browser dashboard only. No Windows settings were changed.',tweaks:allTweaks.map(({id,category,title,risk,mode,reviewed,enabled})=>({id,category,title,risk,mode,reviewed,enabled})),benchmarks:state.benchmarks,history:state.history,bgAppStatus:state.bgAppStatus,profile:state.profile,matchChecklist:state.matchChecklist,notes:state.notes};download('nova-fn-optimizer-backup.json',JSON.stringify(data,null,2));addHistory('Backup exportiert','JSON-Export mit Status, Benchmarks und Notizen','EXPORT');toast('Backup exportiert.');}
function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<2)throw new Error('Die CSV enthält keine Messzeilen.');const headers=splitCsvLine(lines[0]).map(x=>x.trim().toLowerCase());const fpsIdx=headers.findIndex(x=>x==='fps'||x==='frame_rate');const timeIdx=headers.findIndex(x=>x==='timestamp'||x==='time'||x==='frame');const ftIdx=headers.findIndex(x=>x==='frametime_ms'||x==='frametime'||x==='frame_time_ms');if(fpsIdx<0)throw new Error('Spalte „fps“ fehlt. Erwartet: timestamp,fps,frametime_ms.');const rows=[];for(let i=1;i<lines.length;i++){const cols=splitCsvLine(lines[i]);const fps=Number(cols[fpsIdx]);const ft=ftIdx>=0?Number(cols[ftIdx]):1000/fps;if(Number.isFinite(fps)&&fps>0&&Number.isFinite(ft)&&ft>0)rows.push({time:timeIdx>=0?cols[timeIdx]:String(i-1),fps,ft});}if(!rows.length)throw new Error('Keine gültigen FPS-Messwerte gefunden.');return rows}
function splitCsvLine(line){const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'&&q){cur+='"';i++}else if(ch==='"')q=!q;else if(ch===','&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out}
function quantile(a,q){const s=[...a].sort((x,y)=>x-y);return s[Math.min(s.length-1,Math.max(0,Math.ceil(q*s.length)-1))]}
let currentAnalysis=null;
function readCsv(file){if(file.size>5*1024*1024){toast('Datei zu groß: maximal 5 MB.');return}const r=new FileReader();r.onload=()=>{try{const rows=parseCsv(String(r.result));currentAnalysis=analyzeRows(rows,file.name);renderAnalysisOutput(currentAnalysis);$('#save-benchmark').disabled=false;toast(`${rows.length} Samples analysiert.`)}catch(e){currentAnalysis=null;$('#analysis-output').innerHTML=`<section class="panel"><div class="notice"><span class="notice-icon">!</span><div><b>CSV konnte nicht analysiert werden</b><p>${safe(e.message)}</p></div></div></section>`;toast('CSV-Import fehlgeschlagen.')}};r.readAsText(file)}
function analyzeRows(rows,name){const fps=rows.map(x=>x.fps),ft=rows.map(x=>x.ft),avg=fps.reduce((a,b)=>a+b,0)/fps.length,med=quantile(fps,.5),low=quantile(fps,.01),p99=quantile(ft,.99),spikes=ft.filter(x=>x>Math.max(12,avg?1000/avg*1.8:20)).length;return {name,rows,avg,med,min:Math.min(...fps),max:Math.max(...fps),low,p99,spikes,meanFt:ft.reduce((a,b)=>a+b,0)/ft.length}}
function renderAnalysisOutput(a){const max=Math.max(...a.rows.map(r=>r.fps)),min=Math.min(...a.rows.map(r=>r.fps));const points=a.rows.map((r,i)=>`${a.rows.length<2?0:i/(a.rows.length-1)*100},${100-(r.fps-min)/(max-min||1)*80-10}`).join(' ');$('#analysis-output').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Analyse-Ergebnis</h2><p>${safe(a.name)} · ${a.rows.length} gültige Samples</p></div><span class="tag green">BERECHNET</span></div><div class="analyzer-results">${metric('AVG FPS',a.avg.toFixed(1),'Mittelwert')}${metric('MEDIAN',a.med.toFixed(1),'FPS')}${metric('1%-LOW*',a.low.toFixed(1),'FPS')}${metric('MAX FPS',a.max.toFixed(1),'Peak')}${metric('MIN FPS',a.min.toFixed(1),'Tiefstwert')}${metric('MEAN FRAME',a.meanFt.toFixed(2),'ms')}${metric('P99 FRAME',a.p99.toFixed(2),'ms')}${metric('SPIKES',a.spikes,'Heuristik')}</div><div class="chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id="lineFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b7ff3c" stop-opacity=".25"/><stop offset="100%" stop-color="#b7ff3c" stop-opacity="0"/></linearGradient></defs><polygon points="0,100 ${points} 100,100" fill="url(#lineFill)"/><polyline points="${points}" fill="none" stroke="#b7ff3c" stroke-width="1.3" vector-effect="non-scaling-stroke"/></svg></div><p class="chart-note">*1%-Low ist als unteres FPS-Perzentil aus den vorhandenen Samples geschätzt. Spike-Schwelle ist heuristisch, kein offizieller Benchmark-Standard.</p><div class="modal-actions"><button class="btn ghost" data-action="export-analysis">Analyse-CSV exportieren</button><button class="btn ghost" data-action="export-report">Bericht exportieren</button></div></section>`;$$('[data-action="export-analysis"]').forEach(b=>b.addEventListener('click',()=>download('nova-fps-analysis.csv','metric,value\navg_fps,'+a.avg+'\nmedian_fps,'+a.med+'\nlow_1_percent_estimate,'+a.low+'\nmin_fps,'+a.min+'\nmax_fps,'+a.max+'\nmean_frametime_ms,'+a.meanFt+'\np99_frametime_ms,'+a.p99+'\nspike_count,'+a.spikes+'\n','text/csv')));$$('[data-action="export-report"]').forEach(b=>b.addEventListener('click',()=>download('nova-fps-report.json',JSON.stringify({...a,rows:undefined,generatedAt:new Date().toISOString()},null,2))));}
function metric(name,value,desc){return `<div class="metric"><small>${name}</small><b>${value}</b><span>${desc}</span></div>`}
function saveBenchmark(){if(!currentAnalysis){toast('Zuerst eine CSV importieren.');return}const item={id:'BM-'+Date.now(),name:$('#bench-name')?.value||currentAnalysis.name,version:$('#bench-version')?.value||'',notes:$('#bench-notes')?.value||'',date:new Date().toISOString(),avg:+currentAnalysis.avg.toFixed(2),median:+currentAnalysis.med.toFixed(2),low:+currentAnalysis.low.toFixed(2),min:+currentAnalysis.min.toFixed(2),max:+currentAnalysis.max.toFixed(2),p99:+currentAnalysis.p99.toFixed(2),samples:currentAnalysis.rows.length};state.benchmarks.unshift(item);addHistory('Benchmark gespeichert',`${item.name} · Ø ${item.avg} FPS`,'BENCHMARK');saveStored();const savedPanel=$('#saved-benchmarks');if(savedPanel)savedPanel.outerHTML=renderSavedBenchmarks();toast('Benchmark lokal gespeichert.');}
async function runNetwork(button){button.disabled=true;button.textContent='Test läuft …';$('#net-status').textContent='HTTPS-Anfrage wird gemessen. Bitte kurz warten.';const values=[];try{for(let i=0;i<3;i++){const start=performance.now();const res=await fetch('https://www.cloudflare.com/cdn-cgi/trace?nova='+Date.now()+'-'+i,{cache:'no-store',mode:'cors'});if(!res.ok)throw new Error('HTTP '+res.status);await res.text();values.push(performance.now()-start)}const avg=values.reduce((a,b)=>a+b,0)/values.length;$('#net-result').innerHTML=avg.toFixed(0)+' <small>ms</small>';$('#net-status').textContent=`Mittelwert aus 3 HTTPS-Anfragen (${values.map(v=>v.toFixed(0)).join(', ')} ms). Kein In-Game-Ping.`;addHistory('HTTP-Test abgeschlossen',`Mittelwert ${avg.toFixed(0)} ms; drei Anfragen`,'NETWORK');}catch(e){$('#net-result').innerHTML='— <small>ms</small>';$('#net-status').textContent='Test nicht verfügbar: Browser, Netzwerk oder Zielserver blockiert die Anfrage. Das ist kein Fortnite-Ping-Fehler.';toast('HTTP-Test konnte nicht abgeschlossen werden.')}finally{button.disabled=false;button.textContent='HTTP-Test erneut starten ↗';}}
$('#export-all').addEventListener('click',exportAll);$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
if('serviceWorker' in navigator && location.protocol.startsWith('http')) navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
